// Claude: קריאה אחת, עם מקום לחשיבה ומגבלת זמן
const T0 = Date.now(), timeLeft = () => 6.5 * 60000 - (Date.now() - T0); // ריצה אחת מוגבלת ל-9 דקות ב-GitHub
